const userId = $json.jwtPayload?.userId;
if (!userId) return [{ json: { __error: true, __code: 401, __message: 'Token sin userId' } }];
const b = $json.body || {};
const orderId = (b.order_id || '').toString().trim();
const side = (b.side || '').toString().trim();
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(orderId)) return [{ json: { __error: true, __code: 400, __message: 'order_id es requerido' } }];
if (!['front', 'back'].includes(side)) return [{ json: { __error: true, __code: 400, __message: 'side debe ser front o back' } }];
return [{ json: { user_id: String(userId), order_id: orderId, side } }];

const row = $input.first().json;
if (row.ok !== true) return [{ json: { __error: true, __code: 502, __message: 'No se pudo quitar la imagen. Probá de nuevo.' } }];
return [{ json: { __data: { images: row.images || [] }, __message: 'Imagen quitada' } }];
